using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    internal sealed class ResponseErrorConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var document = JsonDocument.ParseValue(ref reader);
            return DeserializeResponseError(document.RootElement);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            if (value.Code != null)
            {
                writer.WritePropertyName("code"u8);
                writer.WriteStringValue(value.Code);
            }
            if (value.Message != null)
            {
                writer.WritePropertyName("message"u8);
                writer.WriteStringValue(value.Message);
            }
            if (value.Target != null)
            {
                writer.WritePropertyName("target"u8);
                writer.WriteStringValue(value.Target);
            }
            if (value.Details != null && value.Details.Count > 0)
            {
                writer.WritePropertyName("details"u8);
                writer.WriteStartArray();
                foreach (var detail in value.Details)
                {
                    Write(writer, detail, options);
                }
                writer.WriteEndArray();
            }
            if (value.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteInnerError(writer, value.InnerError);
            }
            writer.WriteEndObject();
        }

        private static void WriteInnerError(Utf8JsonWriter writer, ResponseInnerError innerError)
        {
            writer.WriteStartObject();
            if (innerError.Code != null)
            {
                writer.WritePropertyName("code"u8);
                writer.WriteStringValue(innerError.Code);
            }
            if (innerError.Message != null)
            {
                writer.WritePropertyName("message"u8);
                writer.WriteStringValue(innerError.Message);
            }
            if (innerError.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteInnerError(writer, innerError.InnerError);
            }
            writer.WriteEndObject();
        }

        internal static ResponseError DeserializeResponseError(JsonElement element)
        {
            string code = null;
            string message = null;
            string target = null;
            ResponseInnerError innerError = null;
            IReadOnlyList<ResponseError> details = null;

            foreach (var property in element.EnumerateObject())
            {
                if (property.NameEquals("code"u8))
                {
                    code = property.Value.GetString();
                }
                else if (property.NameEquals("message"u8))
                {
